import six
from abc import abstractmethod

from .param import ParameterDefinitionBase, ParameterContainerBase


class ParameterDefinition(ParameterDefinitionBase):

    def __init__(self, element):
        super(ParameterDefinition, self).__init__(element)
        self.id = 0
        self.hidden = self._get_hidden(element)
        self.excluded = self._get_excluded(element)
        self.max_occurs = self._get_max_occurs(element)
        self.vendor_specific = self._get_vendor_specific(element)

    def is_array(self):
        """Check if defintion is array."""
        return self.max_occurs > 1

    def get_type_definition(self):
        """Get parameter type definition"""
        return self

    def _get_name(self, element):
        return element.attrib.get('name')

    def _get_hidden(self, element):
        return element.attrib.get('hidden', 'false') == 'true'

    def _get_excluded(self, element):
        excuded_property = element.find(".//property[@name='MO MinOccurs']")
        return excuded_property is not None

    def _get_max_occurs(self, element):
        return int(element.attrib.get('maxOccurs', 1))

    def _get_vendor_specific(self, element):
        vs_property = element.find(".//property[@name='isVendorSpecific']")
        if vs_property is None:
            return False
        return vs_property.attrib.get('value', 'false') == 'true'

    def _get_range(self, element):
        range_elem = element.find(".//range")
        if range_elem is None:
            return (None, None)

        min_val = range_elem.attrib.get('minIncl')
        if min_val is not None:
            min_val = float(min_val)

        max_val = range_elem.attrib.get('maxIncl')
        if max_val is not None:
            max_val = float(max_val)

        return (min_val, max_val)

    def set_id(self, id):
        """Set parameter ID."""
        self.id = id

    @abstractmethod
    def store(self):
        """Check if definition should be strored"""

    def __str__(self):
        array_prefix = "array of " if self.is_array else ""
        return "TypeDefinition. {} : {}{}".format(self.name, array_prefix, self.type_name)


class SimpleParameterDefinition(ParameterDefinition):

    def __init__(self, element):
        self.enum = {}
        super(SimpleParameterDefinition, self).__init__(element)

    def is_simple(self):
        """Check if defintion is simple."""
        return self.type_name in self.simple_types

    def is_enum(self):
        """Check if defintion is enum."""
        return self.type_name == "enum"

    def is_complex(self):
        """Check if defintion is comlex."""
        return False

    def _get_type_name(self, element):
        simple_type_element = element.find('simpleType[@base]')
        if simple_type_element is None:
            raise Exception('Cannot find simpleType element for {}'.format(self.name))

        base = simple_type_element.attrib.get('base')
        if self._is_numeric(base):
            return self._get_numeric_type(simple_type_element)
        return base

    def _is_numeric(self, base):
        return base == 'integer' or base == 'decimal'

    def _get_numeric_type(self, element):
        editing_elem = element.find('./editing[@divisor]')
        if editing_elem is not None:
            return "float"
        if element.find('./enumeration') is not None:
            self._parse_enum_values(element)
            return "enum"
        return "integer"

    def _parse_enum_values(self, element):
        for enum in element.iterfind('./enumeration'):
            value = int(enum.attrib.get('value'))
            text = enum.attrib.get('text')
            self.enum[value] = text
            self.enum[text] = value

    def store(self):
        """Check if definition should be strored"""
        return not (self.hidden or self.excluded) or self.vendor_specific


class ComplexParameterDefinition(ParameterDefinition, ParameterContainerBase):

    def __init__(self, element):
        super(ComplexParameterDefinition, self).__init__(element)
        self.param_list = []
        self.param_dict = {}

        for subelement in self._iter_sublements(element):
            if subelement.find('complexType') is None:
                param = SimpleParameterDefinition(subelement)
            else:
                param = ComplexParameterDefinition(subelement)
            if param.store():
                self.param_dict[param.name] = param
                self.param_list.append(param)
                param.set_id(len(self.param_list))

    def is_simple(self):
        """Check if defintion is simple."""
        return False

    def is_enum(self):
        """Check if defintion is enum."""
        return False

    def is_complex(self):
        """Check if defintion is complex."""
        return True

    def _iter_sublements(self, element):
        return element.iterfind('./complexType/p')

    def _get_type_name(self, element):
        return "complex"

    def store(self):
        """Check if definition should be strored"""
        return True

    def iter_parameters(self):
        """Iterate over internal parameters."""
        return iter(self.param_list)

    def __getitem__(self, param_id):
        if isinstance(param_id, (six.string_types, six.binary_type)):
            return self.param_dict[param_id]
        return self.param_list[param_id - 1]


class ManagedObjectDefinition(ComplexParameterDefinition):

    def __init__(self, element):
        super(ManagedObjectDefinition, self).__init__(element)

    def _iter_sublements(self, element):
        return element.iterfind('./p')

    def _get_name(self, element):
        return element.attrib.get('class')
